INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 1, 'Soak: Soak corn and beans overnight in water.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 2, 'Cook Meats: In a large pot, brown the beef and pork. Add onions and spices, cooking until translucent.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 3, 'Simmer the Stew: Add soaked corn and beans, pumpkin, potato, and enough water to cover. Simmer for 2-3 hours, until thick.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 4, 'Serve: Enjoy hot, with bread on the side.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 5, 'Pro Tips:');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 6, 'Toasting the corn slightly before adding it to the stew enhances its flavor.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf9a', 7, 'Add a spoonful of paprika or a dash of cumin for an extra layer of warmth and complexity');
