INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 1, 'Heat oil in a deep fryer or deep heavy skillet to 365°F (185°C).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 2, 'Warm gravy in saucepan or microwave.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 3, 'Place the fries into the hot oil, and cook until light brown, about 5 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 4, 'Remove to a paper towel lined plate to drain.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 5, 'Place the fries on a serving platter, and sprinkle the cheese over them.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce44', 6, 'Ladle gravy over the fries and cheese, and serve immediately.');
