INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d087', 1, 'Boil: Bring water to a boil, gently add eggs, and cook for exactly 6½ to 7 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d087', 2, 'Ice Bath: Immediately transfer the eggs to a bowl of ice water for 3–5 minutes to stop cooking.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d087', 3, 'Marinate (Optional but recommended): Peel the eggs and marinate in a mix of 2 tbsp soy sauce, 2 tbsp mirin, 1 tsp sugar, and 4 tbsp water for at least 4 hours (or overnight).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d087', 4, 'Serve: Slice in half, letting the yolk flow into the broth');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cfdf', 'Shakshouka', 'Danie: Saudi Arabian. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
